// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"circulating-supply":{"slug":"circulating-supply","cat":"basics","en":"Circulating supply","contentLocale":"tr","term":"Dolaşımdaki arz (circulating supply)","aka":["dolaşım arzı","circulating supply"],"short":"Dolaşımdaki arz, bir kripto paranın şu anda piyasada serbestçe alınıp satılabilen, kilitli veya rezervde tutulmayan coin ya da token miktarıdır.","body":["Bir token için genellikle üç rakam görürsünüz: dolaşımdaki arz, toplam arz ve maksimum arz. Toplam arz, şu ana kadar oluşturulmuş ama bir kısmı kilitli olabilecek miktardır. Maksimum arz ise hiçbir zaman aşılmayacak üst sınırdır; her token'da böyle bir sınır yoktur.","Dolaşımdaki arz, piyasa değerinin hesaplandığı temeldir. Token kilitleri açıldıkça bu rakam büyür; yakma (burn) yapıldıkça küçülebilir. Arz artışı, talep aynı kalırsa fiyat üzerinde baskı oluşturabilir.",["Rakamlar proje beyanlarına ve veri sitelerinin metodolojisine dayanır. Kaybolmuş cüzdanlardaki coinler veya hazine cüzdanlarındaki token'lar farklı şekilde sayılabilir. Bu yüzden önemli kararlarda projenin ",["token ekonomisi","tokenomics"]," belgesini de kontrol etmek faydalıdır."]],"example":["Bir token'ın toplam arzı 500 milyon, dolaşımdaki arzı 150 milyon ve fiyatı 0,80 ",["USDT","usdt"]," olsun. ",["Piyasa değeri","market-capitalization"]," 0,80 x 150.000.000 = 120 milyon USDT'dir. Önümüzdeki ay 25 milyon token'ın kilidi açılırsa dolaşım 175 milyona çıkar. Piyasa değeri aynı 120 milyon USDT'de kalırsa fiyat 120.000.000 / 175.000.000 = yaklaşık 0,686 USDT'ye iner, yani yaklaşık yüzde 14 düşüş anlamına gelir."],"mistakes":["Toplam arz ile dolaşımdaki arzı aynı şey sanmak.","Yaklaşan kilit açılmalarının dolaşımdaki arzı ne kadar artıracağını hesaplamamak.","Maksimum arz sınırı olmayan bir token'ın arzının sabit kalacağını varsaymak."],"faq":[{"q":"Dolaşımdaki arz neden değişir?","a":"Yeni coinler madencilik veya staking ödülleriyle çıkar, kilitli token'lar açılır ya da token'lar yakılır. Bu olayların her biri dolaşımdaki miktarı artırır veya azaltır."},{"q":"Bitcoin'in dolaşımdaki arzı ne kadar?","a":"Üretilen BTC miktarı her blokla artar ve maksimum 21 milyona yaklaşır. Güncel rakamı bir blok gezgininden veya veri sitesinden kontrol edebilirsiniz."}],"title":"Dolaşımdaki arz nedir? Toplam ve maksimum arz farkı","description":"Dolaşımdaki arzın ne olduğunu, toplam ve maksimum arzdan farkını ve kilit açılmalarının fiyatı nasıl etkileyebileceğini öğrenin.","related":[["market-capitalization","Piyasa değeri (market cap)","Piyasa değeri (market cap), bir kripto paranın güncel fiyatının dolaşımdaki arzla çarpılmasıyla bulunan toplam değerdir ve coinlerin büyüklüğünü karşılaştırmak için kullanılır."],["fully-diluted-valuation","Tam seyreltilmiş değer (FDV)","Tam seyreltilmiş değer (FDV), bir token'ın güncel fiyatının maksimum veya toplam arzla çarpılmasıyla bulunan değerdir ve tüm token'lar piyasaya çıktığında projenin ne kadar büyük görüneceğini gösterir."],["token-unlock","Token kilit açılımı (token unlock)","Token kilit açılımı (token unlock), ekip, yatırımcılar veya ekosistem fonu için önceden kilitlenmiş token'ların belirlenmiş bir takvime göre serbest bırakılıp alınıp satılabilir hale gelmesidir."],["token-burn","Token yakımı (token burn)","Token yakımı (token burn), token'ların kimsenin erişemeyeceği bir adrese gönderilerek veya kontrat tarafından imha edilerek dolaşımdan kalıcı olarak çıkarılmasıdır."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"bear-market":{"slug":"bear-market","cat":"basics","en":"Bear market","contentLocale":"tr","term":"Ayı piyasası (bear market)","aka":["ayı sezonu","bear market","ayı"],"short":"Ayı piyasası (bear market), fiyatların uzun bir dönem boyunca genel olarak düştüğü, yatırımcı karamsarlığının ve düşük ilginin hakim olduğu piyasa evresidir.","body":["Ayı adı, hayvanın pençesini yukarıdan aşağı indirmesinden gelir. Hisse senedi piyasasında zirveden yüzde 20'lik düşüş sık kullanılan bir ölçüttür; kripto piyasasında ise ayı dönemlerinde zirveden yüzde 70-80'lik düşüşler de yaşanmıştır.",["Ayı piyasasında işlem hacmi azalır, birçok küçük proje ortadan kalkar ve haber akışı olumsuzlaşır. Ani ve güçlü yükselişler (ayı piyasası rallisi) görülebilir ama genel eğilim aşağı yönlü kalır. Bu dönemlerde short pozisyonlar ve ",["stablecoin","stablecoin"],"'de beklemek daha çok konuşulur."],["Uzun vadeli yatırımcıların bir kısmı bu dönemde düzenli alım (",["DCA","dollar-cost-averaging"],") yapmayı tercih eder. Ancak dibin nerede olduğunu kimse önceden bilemez; düşen bir varlık daha da düşebilir. Pozisyon büyüklüğünü ve nakit ihtiyacınızı buna göre planlamanız gerekir."]],"example":["Bir coin zirvede 4.000 ",["USDT","usdt"]," iken ayı piyasasında 1.000 USDT'ye düşerse kayıp yüzde 75'tir. Önemli bir ayrıntı: yüzde 75 düşüşten sonra başlangıç seviyesine dönmek için fiyatın yüzde 300 yükselmesi gerekir (1.000'den 4.000'e). Bu dönemde ayda 100 USDT ile düzenli alım yapan biri, fiyat 2.000'deyken 0,05, 1.000'deyken 0,1 coin alır; ortalama maliyeti tek seferlik alıma göre düşer ama fiyatın yeniden yükseleceğinin garantisi yoktur."],"mistakes":["Ayı piyasası rallisini yeni bir boğa piyasasının kesin başlangıcı sanıp tüm nakdi bir anda kullanmak.","Düşen bir varlıkta ortalama düşürmek için kaldıraç kullanmak.","Kısa vadede ihtiyaç duyacağınız parayı uzun sürebilecek bir düşüş döneminde riske atmak."],"faq":[{"q":"Ayı piyasasında ne yapılır?","a":"Yatırımcılar risklerini azaltabilir, stablecoin'de bekleyebilir veya planlı düzenli alımlar yapabilir. Hangi yaklaşımın uygun olduğu zaman ufkunuza ve risk toleransınıza bağlıdır."},{"q":"Ayı piyasasının bittiği nasıl anlaşılır?","a":"Kesin bir sinyal yoktur. Daha yüksek dipler, artan hacim ve iyileşen piyasa duyarlılığı sık bakılan işaretlerdir, ama bunlar da yanıltıcı olabilir."}],"title":"Ayı piyasası (bear market) nedir?","description":"Ayı piyasasının ne olduğunu, kriptoda düşüşlerin ne kadar derin olabildiğini ve bu dönemde riskleri nasıl yöneteceğinizi öğrenin.","related":[["bull-market","Boğa piyasası (bull market)","Boğa piyasası (bull market), fiyatların uzun bir dönem boyunca genel olarak yükseldiği, yatırımcı iyimserliğinin ve işlem hacminin arttığı piyasa evresidir."],["fud","FUD (korku, belirsizlik ve şüphe)","FUD (fear, uncertainty and doubt), bir kripto para veya proje hakkında korku, belirsizlik ve şüphe yaratan haberler, söylentiler ya da yorumlar için kullanılan bir terimdir."],["dollar-cost-averaging","Düzenli alım stratejisi (DCA)","DCA (dollar-cost averaging), fiyatı tahmin etmeye çalışmadan belirli aralıklarla sabit tutarda kripto alarak ortalama maliyeti zamana yayma stratejisidir."],["short-selling","Açığa satış (Short selling)","Açığa satış (short selling), fiyatın düşeceği beklentisiyle bir varlığı sahip olmadan satıp daha sonra daha düşük fiyattan geri alarak aradaki farktan kazanç sağlama işlemidir."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"leverage":{"slug":"leverage","cat":"derivatives","en":"Leverage","contentLocale":"tr","term":"Kaldıraç (Leverage)","aka":["kaldıraçlı işlem","leverage","çarpan"],"short":"Kaldıraç, yatırdığınız teminatın birkaç katı büyüklüğünde pozisyon açmanızı sağlayan ve hem kazancı hem kaybı aynı oranda büyüten bir işlem aracıdır.","body":[["10x kaldıraç, 100 ",["USDT","usdt"]," teminatla 1.000 USDT'lik pozisyon açabileceğiniz anlamına gelir. Fiyat yüzde 1 lehinize hareket ederse teminatınıza göre yüzde 10 kazanırsınız; aleyhinize hareket ederse yüzde 10 kaybedersiniz. Kaldıraç piyasanın riskini değiştirmez, sizin o riske maruz kalma miktarınızı büyütür."],["Kaldıraç ne kadar yüksekse ",["likidasyon (tasfiye)","liquidation"]," fiyatı giriş fiyatına o kadar yakın olur. 50x kaldıraçta yaklaşık yüzde 2'lik ters bir hareket, ",["bakım teminatı","maintenance-margin"]," da hesaba katıldığında daha da azı, teminatın tamamını silmeye yeter. Kripto fiyatlarının gün içinde birkaç yüzde oynaması olağan olduğu için yüksek kaldıraç çok hızlı tasfiyeye yol açabilir."],"Borsalar pozisyon büyüdükçe izin verilen maksimum kaldıracı düşürür ve kaldıraç sınırları ülke düzenlemelerine göre değişebilir. Kaldıracı pozisyon büyüklüğünü belirlemek için değil, teminatı verimli kullanmak için düşünmek daha sağlıklıdır."],"example":["Elinizde 1.000 USDT var. 5x kaldıraçla 5.000 USDT'lik ",["BTC","bitcoin"]," long açarsanız ve BTC yüzde 4 düşerse kaybınız 200 USDT, yani teminatın yüzde 20'si olur. Aynı 1.000 USDT ile 25x kaldıraçta 25.000 USDT'lik pozisyon açarsanız yüzde 4'lük düşüş 1.000 USDT kayıp demektir; izole marjinde bakım teminatı nedeniyle pozisyon bu noktaya gelmeden, yaklaşık yüzde 3,5 civarında tasfiye edilir."],"mistakes":["Kaldıracı ne kadar kazanacağınıza göre seçip ne kadar hızlı tasfiye olabileceğinizi hesaplamamak.","Kaldıraç ayarını değiştirince pozisyon büyüklüğünün de otomatik değiştiğini sanmak; birçok borsada miktarı ayrıca girersiniz.","Fonlama ve işlem ücretlerinin nominal pozisyon üzerinden alındığını unutmak."],"faq":[{"q":"Yeni başlayan için kaç kat kaldıraç uygundur?","a":"Tek bir doğru sayı yoktur, ama düşük kaldıraç likidasyon fiyatını girişten uzak tutar ve hata payı bırakır. Önemli olan stop seviyenize göre pozisyon büyüklüğünü belirlemek ve tasfiye fiyatının stop'tan uzakta olmasıdır."},{"q":"Kaldıraçlı işlemde teminattan fazla kaybedebilir miyim?","a":"Çoğu kripto borsasında izole marjinde kaybınız o pozisyonun teminatıyla sınırlıdır. Çapraz marjinde ise hesaptaki diğer bakiyeler de risk altına girer."}],"title":"Kaldıraç nedir? Kripto kaldıraçlı işlem nasıl çalışır","description":"Kripto kaldıracının nasıl çalıştığını, kazanç ve kaybı nasıl büyüttüğünü ve tasfiye fiyatına etkisini öğrenin.","related":[["margin-trading","Marjin ticareti (Margin trading)","Marjin ticareti, hesabınızdaki varlıkları teminat göstererek borsadan borç alıp sahip olduğunuzdan daha büyük pozisyon açtığınız işlem türüdür."],["liquidation-price","Likidasyon fiyatı (Liquidation price)","Likidasyon fiyatı, kaldıraçlı bir pozisyonun teminatının bakım seviyesine indiği ve borsanın pozisyonu zorla kapatmaya başladığı işaret fiyatı seviyesidir."],["initial-margin","Başlangıç teminatı (Initial margin)","Başlangıç teminatı, kaldıraçlı bir pozisyonu açabilmek için hesabınızda bulunması ve pozisyona bağlanması gereken asgari teminat tutarıdır."],["isolated-margin","İzole marjin (Isolated margin)","İzole marjin, her pozisyona ayrı bir teminat ayrıldığı ve olası kaybın yalnızca o pozisyona bağlanan teminatla sınırlı kaldığı marjin modudur."],["position-sizing","Pozisyon büyüklüğü (Position sizing)","Pozisyon büyüklüğü, bir işleme ne kadar sermaye ayıracağınızı zarar durdur seviyenize ve kabul edebileceğiniz en yüksek kayba göre belirleme yöntemidir."]],"lesson":{"id":"E19","slug":"what-leverage-does","ep":19,"title":"10x kaldıraç: Daha fazla para mı, daha fazla risk mi?"},"coin":null,"tool":"/liquidations","cta":true},"auto-deleveraging":{"slug":"auto-deleveraging","cat":"derivatives","en":"Auto-deleveraging (ADL)","contentLocale":"tr","term":"Otomatik kaldıraç azaltma (ADL)","aka":["ADL","auto-deleveraging","otomatik pozisyon azaltma"],"short":"Otomatik kaldıraç azaltma (ADL), tasfiye edilen bir pozisyonun zararı sigorta fonuyla karşılanamadığında, borsanın karşı taraftaki kârlı ve yüksek kaldıraçlı pozisyonları otomatik olarak kısmen kapatmasıdır.","body":[["Normalde tasfiye edilen bir pozisyon piyasada kapatılır ve olası açık sigorta fonundan karşılanır. Çok sert hareketlerde ise pozisyon ",["likidasyon","liquidation"]," fiyatından çok daha kötü bir fiyatla kapanabilir ve ",["sigorta fonu","insurance-fund"]," yetmeyebilir. Bu durumda borsa, karşı tarafta kâr eden işlemcilerin pozisyonlarını iflas fiyatından kapatarak açığı dengeler."],["ADL sırası genellikle kâr oranı ve ",["kaldıraç","leverage"]," kombinasyonuna göre belirlenir: en kârlı ve en yüksek kaldıraçlı pozisyonlar listenin başındadır. Birçok borsa arayüzde pozisyonunuzun ADL sırasını birkaç ışık veya çubukla gösterir. Işık sayısı arttıkça ADL'ye maruz kalma olasılığınız yükselir."],"ADL'de para kaybetmezsiniz; pozisyonunuz o ana kadarki kârıyla kapatılır. Ancak kârlı bir pozisyonunuz isteğiniz dışında kapanır ve planladığınız ek kazancı kaçırabilirsiniz. ADL'nin tetiklenme koşulları ve sıralama yöntemi borsaya göre değişir."],"example":["Sert bir düşüşte büyük bir ",["long pozisyon","long-and-short"]," 41.000 ",["USDT","usdt"],"'den tasfiye edilmesi gerekirken defterde alıcı olmadığı için 39.500 USDT'ye kadar inmek zorunda kalıyor ve 450.000 USDT açık oluşuyor. Sigorta fonu bu kontrat için yalnızca 300.000 USDT karşılayabiliyor. Kalan 150.000 USDT için borsa, en kârlı ve en yüksek kaldıraçlı short pozisyonlardan biri olan sizin 20x short'unuzu 0,5 ",["BTC","bitcoin"]," kadar kapatıyor. Pozisyonunuzun kalan kısmı açık kalıyor."],"mistakes":["ADL ışıklarının ne anlama geldiğini bilmeden yüksek kaldıraçlı kârlı pozisyonu uzun süre açık tutmak.","ADL'yi likidasyonla karıştırmak; ADL'de pozisyon zararda değil kârda kapanır.","ADL sonrası kapanan hedge bacağını fark etmeyip tek yönlü riskte kalmak."],"faq":[{"q":"ADL'de para kaybeder miyim?","a":"Hayır, pozisyonunuz o ana kadarki kârıyla kapatılır. Ancak pozisyon isteğiniz dışında kapandığı için sonraki olası kazancı kaçırabilir veya hedge yapınız bozulabilir."},{"q":"ADL riskini nasıl azaltırım?","a":"Kaldıracı düşürmek ve büyük kârları kademeli olarak realize etmek ADL sıranızı geriye çeker. Hedge pozisyonlarında ADL sonrası diğer bacağı kontrol etmek önemlidir."}],"title":"ADL (otomatik kaldıraç azaltma) nedir?","description":"Otomatik kaldıraç azaltmanın ne zaman devreye girdiğini, ADL sırasının nasıl belirlendiğini ve riskini öğrenin.","related":[["insurance-fund","Sigorta fonu (Insurance fund)","Sigorta fonu, vadeli işlem borsalarının tasfiye edilen pozisyonların teminatı aşan zararlarını karşılamak ve otomatik kaldıraç azaltmayı (ADL) önlemek için tuttuğu rezerv fondur."],["liquidation","Likidasyon (Tasfiye)","Likidasyon (tasfiye), kaldıraçlı bir pozisyonun teminatı bakım seviyesinin altına düştüğünde borsanın pozisyonu zorla kapatmasıdır."],["unrealized-pnl","Gerçekleşmemiş kâr/zarar (Unrealized PnL)","Gerçekleşmemiş kâr/zarar (unrealized PnL), açık bir pozisyonun mevcut fiyata göre hesaplanan ama pozisyon kapatılmadığı için henüz kesinleşmemiş kâr veya zararıdır."],["leverage","Kaldıraç (Leverage)","Kaldıraç, yatırdığınız teminatın birkaç katı büyüklüğünde pozisyon açmanızı sağlayan ve hem kazancı hem kaybı aynı oranda büyüten bir işlem aracıdır."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"Tasfiye: Zorunlu kapatma butonuna kim bastı?"},"coin":null,"tool":"/liquidations","cta":false},"crypto-wallet":{"slug":"crypto-wallet","cat":"wallets-security","en":"Crypto wallet","contentLocale":"tr","term":"Kripto cüzdan (Crypto wallet)","aka":["kripto para cüzdanı","cüzdan","wallet","dijital cüzdan"],"short":"Kripto cüzdan, kripto varlıklarınıza erişmenizi sağlayan özel anahtarları saklayan ve bu anahtarlarla işlem imzalamanıza imkân veren yazılım veya donanımdır.","body":[["Adı yanıltıcı olsa da cüzdan coinleri içinde tutmaz; coinler blok zincirinde kayıtlıdır. Cüzdan, o kayıtlar üzerinde işlem yapma yetkisi veren özel anahtarı (",["private key","private-key"],") saklar ve size para almak için kullanacağınız cüzdan adresini gösterir. Özel anahtara sahip olan, varlıkları kontrol eder."],["Cüzdanlar iki ana gruba ayrılır. Emanetçi (custodial) cüzdanlarda anahtarları borsa gibi bir kurum tutar; giriş kolaydır ama kuruma güvenmeniz gerekir. Emanetçi olmayan (non-custodial) cüzdanlarda anahtarlar sizdedir ve genellikle 12 veya 24 kelimelik bir kurtarma ifadesiyle (",["seed phrase","seed-phrase"],") yedeklenir."],["Ayrıca internete bağlı uygulama ve tarayıcı eklentisi cüzdanlarına ",["sıcak cüzdan","hot-wallet"],", anahtarları çevrimdışı tutan donanım cüzdanlarına ",["soğuk cüzdan","cold-wallet"]," denir. Hangi cüzdanın uygun olduğu, ne kadar varlık tuttuğunuza ve ne sıklıkla işlem yaptığınıza bağlıdır."]],"example":["Borsadan 0,05 ",["BTC","bitcoin"],"'yi kendi mobil cüzdanınıza çekmek istiyorsunuz. Cüzdan size bir BTC adresi gösterir; bu adresi borsanın çekim ekranına yapıştırır ve Bitcoin ağını seçersiniz. Borsa ",["çekim ücreti","withdrawal-fee"]," olarak örneğin 0,0002 BTC keserse cüzdanınıza 0,0498 BTC ulaşır. Bu andan itibaren varlığa erişim, telefonunuzdaki özel anahtara ve kâğıda yazdığınız 12 kelimelik kurtarma ifadesine bağlıdır."],"mistakes":["Kurtarma ifadesini telefonda ekran görüntüsü veya bulut notu olarak saklamak.","Para gönderirken ağı ve adresi kontrol etmeden işlem yapmak.","Destek görevlisi olduğunu söyleyen birine kurtarma ifadesini veya özel anahtarı vermek."],"faq":[{"q":"En güvenli kripto cüzdan hangisi?","a":"Büyük tutarlar için genellikle donanım cüzdanları en güvenli seçenek olarak görülür, çünkü anahtarlar çevrimdışı kalır. Güvenlik, cüzdanın türü kadar kurtarma ifadesini nasıl sakladığınıza da bağlıdır."},{"q":"Borsadaki hesap bir cüzdan mıdır?","a":"Borsa hesabı emanetçi bir cüzdan gibi çalışır; anahtarları borsa tutar. Varlığın tam kontrolü için anahtarları sizde olan bir cüzdan gerekir."}],"title":"Kripto cüzdan nedir? Türleri ve nasıl çalışır","description":"Kripto cüzdanın ne olduğunu, özel anahtar ve kurtarma ifadesinin rolünü ve cüzdan türlerini öğrenin.","related":[["custodial-wallet","Emanetçi cüzdan (Custodial wallet)","Emanetçi cüzdan (custodial wallet), kripto varlıklarınızın özel anahtarlarını sizin yerinize bir borsanın veya saklama kuruluşunun tuttuğu cüzdan türüdür."],["non-custodial-wallet","Saklama dışı cüzdan (non-custodial wallet)","Saklama dışı cüzdan, özel anahtarları yalnızca sizin kontrol ettiğiniz, bu yüzden fonlarınızı sizden başka kimsenin taşıyamadığı, donduramadığı veya sizin yerinize kurtaramadığı bir kripto cüzdanıdır."],["seed-phrase","Kurtarma ifadesi (seed phrase)","Kurtarma ifadesi (seed phrase), bir kripto cüzdanının tüm özel anahtarlarının türetildiği 12 veya 24 kelimelik listedir ve bu kelimeleri bilen herkes cüzdanın tamamını kontrol edebilir."],["wallet-address","Cüzdan adresi (wallet address)","Cüzdan adresi, bir blokzincirde kripto almak için paylaştığınız, açık anahtardan türetilen harf ve rakamlardan oluşan bir dizidir; banka hesap numarasına benzer ama ağa özgüdür."],["hardware-wallet","Donanım cüzdanı (hardware wallet)","Donanım cüzdanı, özel anahtarları güvenli bir çip içinde çevrim dışı saklayan ve işlemleri cihazın kendi ekranında onaylatarak imzalayan küçük bir fiziksel cihazdır."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Coin'lerim nerede? Borsa ve cüzdan farkı"},"coin":null,"tool":null,"cta":false},"memo-tag":{"slug":"memo-tag","cat":"wallets-security","en":"Memo / destination tag","contentLocale":"tr","term":"Memo / hedef etiketi (destination tag)","aka":["memo","tag","destination tag","etiket"],"short":"Memo veya hedef etiketi, bazı coinlerde borsaya yapılan bir yatırmanın hangi kullanıcıya ait olduğunu belirlemek için adresin yanında gönderilen ek koddur.","body":[["XRP, XLM, ATOM, EOS, TON gibi bazı ağlarda borsalar tüm kullanıcılar için tek bir ortak ",["yatırma adresi","wallet-address"]," kullanır. Paranın kime ait olduğunu ayırt etmek için her kullanıcıya özel bir memo, tag veya comment verilir. XRP'de buna destination tag denir."],"Memo'yu boş bırakırsanız veya yanlış yazarsanız, fonlar borsanın adresine ulaşır ama hesabınıza otomatik olarak yansımaz. Bu durumda genellikle destek ekibine işlem hash'iyle başvurmanız gerekir. Süreç uzun sürebilir ve bazı borsalar ücret alabilir.","Kendi saklama dışı cüzdanınıza gönderirken memo çoğu zaman gerekmez, çünkü adres yalnızca size aittir. Yine de borsanın çekim ekranı memo alanını zorunlu gösterirse alıcı tarafın talimatını kontrol edin."],"example":["C borsasından D borsasına 150 XRP göndermek istiyorsunuz. D borsasının yatırma sayfasında bir adres ve 104829 numaralı bir destination tag görüyorsunuz. Çekim ekranında adresi yapıştırır, tag alanına 104829 yazarsınız. ",["Çekim ücreti","withdrawal-fee"]," örneğin 0,2 XRP ise D hesabınıza 149,8 XRP yansır. Tag'i boş bıraksaydınız 149,8 XRP borsanın ortak adresine düşer, ama hesabınıza otomatik olarak geçmezdi."],"mistakes":["Memo alanını isteğe bağlı sanıp boş bırakmak.","Memo'yu adresin sonuna eklemek yerine ayrı alana yazmamak.","Bir borsanın eski memo'sunu kayıtlardan kopyalamak; kullanıcıya özel değer değişmiş olabilir."],"faq":[{"q":"Memo olmadan gönderilen kripto kaybolur mu?","a":"Genellikle kaybolmaz ama hesabınıza otomatik geçmez. Borsanın destek ekibine işlem hash'i ve hesap bilginizle başvurarak kurtarma talep edebilirsiniz."},{"q":"Hangi coinler memo gerektirir?","a":"XRP, XLM, ATOM, EOS ve TON gibi bazı coinlerde borsalar memo veya tag kullanır. Gereklilik borsaya göre değişebildiği için yatırma sayfasını kontrol edin."}],"title":"Memo ve destination tag nedir? Ne zaman gerekir?","description":"Memo ve hedef etiketinin ne olduğunu, hangi coinlerde gerektiğini ve unutulursa fonların nasıl kurtarılacağını öğrenin.","related":[["wallet-address","Cüzdan adresi (wallet address)","Cüzdan adresi, bir blokzincirde kripto almak için paylaştığınız, açık anahtardan türetilen harf ve rakamlardan oluşan bir dizidir; banka hesap numarasına benzer ama ağa özgüdür."],["blockchain-network","Yatırma ağı (ağ seçimi)","Yatırma ağı, bir kripto varlığı transfer ederken işlemin hangi blokzincir üzerinden gideceğini belirleyen seçimdir; gönderen ve alan tarafın aynı ağı desteklemesi gerekir."],["transaction-hash","İşlem hash'i (TxID)","İşlem hash'i (TxID), blokzincire gönderilen her işleme verilen benzersiz kimlik kodudur ve işlemin durumunu bir blok gezgininde takip etmenizi sağlar."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Transferden önce: Bunların hiçbirini tahminle yapma"},"coin":null,"tool":null,"cta":false},"two-factor-authentication":{"slug":"two-factor-authentication","cat":"wallets-security","en":"Two-factor authentication (2FA)","contentLocale":"tr","term":"İki faktörlü doğrulama (2FA)","aka":["2FA","iki adımlı doğrulama","Google Authenticator","two-factor authentication"],"short":"İki faktörlü doğrulama (2FA), hesabınıza girişte veya çekimde şifrenin yanında ikinci bir kanıt, örneğin bir doğrulama uygulamasından gelen 6 haneli kod istenmesini sağlayan güvenlik katmanıdır.","body":[["Şifre tek başına yeterli değildir; veri sızıntıları ve ",["oltalama","phishing"]," siteleri şifreleri kolayca ele geçirebilir. 2FA ile saldırganın şifrenize ek olarak telefonunuzdaki uygulamaya veya fiziksel güvenlik anahtarınıza da erişmesi gerekir."],"Kripto borsalarında yaygın 2FA türleri SMS kodu, e-posta kodu, Google Authenticator gibi zaman tabanlı kod uygulamaları (TOTP), passkey ve YubiKey gibi donanım güvenlik anahtarlarıdır. SMS, SIM kart değiştirme (SIM swap) saldırılarına karşı daha zayıftır; doğrulama uygulaması veya donanım anahtarı daha güçlü kabul edilir.",["2FA'yı kurarken verilen yedek anahtarı (QR kodun altındaki metin) güvenli bir yere yazmalısınız. Telefonunuz kaybolursa bu anahtar olmadan hesabınıza erişimi geri almak, borsanın ",["kimlik doğrulama","kyc"]," sürecinden geçmeyi gerektirir ve günler sürebilir."]],"example":["Şifrenizin bir veri sızıntısında yayınlandığını varsayalım. Saldırgan e-posta ve şifrenizle giriş yapmayı dener ama sistem 6 haneli bir doğrulama kodu ister. Bu kod telefonunuzdaki uygulamada her 30 saniyede bir değişir. Saldırgan kodu bilmediği için giriş başarısız olur ve hesabınızdaki 2.500 ",["USDT","usdt"]," güvende kalır. Siz de bildirim e-postasını görünce şifrenizi hemen değiştirirsiniz."],"mistakes":["Sadece SMS doğrulamasına güvenmek ve daha güçlü bir yöntem eklememek.","2FA yedek anahtarını kaydetmeden telefonu sıfırlamak veya değiştirmek.","Telefonla arayan \"destek\" kişisine 6 haneli kodu söylemek."],"faq":[{"q":"Hangi 2FA yöntemi en güvenli?","a":"Donanım güvenlik anahtarları ve passkey'ler genellikle en güçlü seçeneklerdir. Doğrulama uygulamaları SMS'ten daha güvenlidir."},{"q":"2FA telefonumu kaybedersem ne yaparım?","a":"Yedek anahtarınız varsa yeni telefona kurarsınız. Yoksa borsanın hesap kurtarma sürecine başvurmanız gerekir; bu süreç kimlik doğrulaması isteyebilir."}],"title":"2FA (iki faktörlü doğrulama) nedir? Kripto hesabı güvenliği","description":"İki faktörlü doğrulamanın nasıl çalıştığını, SMS ile doğrulama uygulaması farkını ve yedek anahtarın önemini öğrenin.","related":[["anti-phishing-code","Oltalama karşıtı kod (anti-phishing code)","Oltalama karşıtı kod, borsa hesabınızda belirlediğiniz ve borsanın size gönderdiği gerçek e-postalarda görünen kişisel bir kelimedir; bu kodu içermeyen e-postaların sahte olma ihtimali yüksektir."],["withdrawal-whitelist","Çekim beyaz listesi (withdrawal whitelist)","Çekim beyaz listesi, borsa hesabınızdan yalnızca önceden kaydedip onayladığınız adreslere kripto çekilmesine izin veren bir güvenlik ayarıdır."],["phishing","Oltalama (phishing)","Oltalama (phishing), dolandırıcıların sahte web siteleri, e-postalar, mesajlar veya reklamlar kullanarak sizden şifre, 2FA kodu, kurtarma ifadesi almaya ya da zararlı bir işlemi imzalatmaya çalıştığı saldırıdır."],["sub-account","Alt hesap (sub-account)","Alt hesap, ana borsa hesabınıza bağlı, ayrı bakiyesi, ayrı API anahtarları ve ayrı risk ayarları olan ek bir hesaptır; stratejileri ve riskleri birbirinden ayırmak için kullanılır."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"Gerçek kapıyı bul: Körlemesine hesap açma"},"coin":null,"tool":null,"cta":false},"withdrawal-whitelist":{"slug":"withdrawal-whitelist","cat":"wallets-security","en":"Withdrawal whitelist","contentLocale":"tr","term":"Çekim beyaz listesi (withdrawal whitelist)","aka":["adres beyaz listesi","withdrawal whitelist","güvenilir adres listesi"],"short":"Çekim beyaz listesi, borsa hesabınızdan yalnızca önceden kaydedip onayladığınız adreslere kripto çekilmesine izin veren bir güvenlik ayarıdır.","body":["Beyaz liste açık olduğunda, hesabınıza giren biri bakiyenizi kendi adresine çekemez; çünkü yeni bir adres eklemek ek doğrulama ister. Birçok borsada yeni adres eklendiğinde 24 saate kadar bir çekim kilidi de uygulanır. Bu süre ve kurallar borsadan borsaya değişir.",["Beyaz liste aynı zamanda yazım hatalarına karşı da korur. Adresi bir kez dikkatlice kontrol edip etiketlediğinizde (örneğin \"",["Donanım cüzdanı","hardware-wallet"]," ",["BTC","bitcoin"],"\"), her çekimde listeden seçer ve tekrar kopyala-yapıştır yapmazsınız. Bu, ",["adres zehirleme","address-poisoning"]," ve pano değiştiren zararlı yazılımlara karşı riski azaltır."],"Bir dezavantajı esnekliğin azalmasıdır: acil bir transferde yeni adres eklemek için beklemeniz gerekebilir. Bu yüzden sık kullandığınız adresleri önceden eklemek mantıklıdır."],"example":["Hesabınızda 1,2 ",["ETH","ethereum"]," var ve beyaz listenizde yalnızca kendi donanım cüzdanınız kayıtlı. Bir saldırgan şifrenizi ve oturumunuzu ele geçirip 1,2 ETH'yi kendi adresine çekmek ister. Sistem yeni adres için e-posta onayı, ",["2FA","two-factor-authentication"]," kodu ve 24 saatlik bekleme ister. Siz bu sürede bildirim e-postasını görür, şifrenizi değiştirir ve oturumları kapatırsınız. 1,2 ETH hesapta kalır."],"mistakes":["Beyaz listeyi açıp e-posta veya 2FA güvenliğini zayıf bırakmak.","Adres eklerken ağ türünü yanlış seçmek; aynı adres farklı ağda başka anlam taşıyabilir.","Listeye eklenen adresi işlem geçmişinden kopyalamak."],"faq":[{"q":"Beyaz liste açıkken yeni adrese çekim yapabilir miyim?","a":"Önce adresi listeye eklemeniz ve doğrulamanız gerekir. Bazı borsalar bundan sonra kısa bir bekleme süresi uygular."},{"q":"Beyaz liste hesabı tamamen korur mu?","a":"Çekim riskini azaltır ama hesaptaki işlemleri, örneğin kötü niyetli alım satımları engellemez. 2FA ve güçlü şifre ile birlikte kullanılmalıdır."}],"title":"Çekim beyaz listesi nedir? Nasıl çalışır?","description":"Çekim beyaz listesinin hesabınızı nasıl koruduğunu, yeni adres bekleme sürelerini ve doğru kullanım ipuçlarını öğrenin.","related":[["wallet-address","Cüzdan adresi (wallet address)","Cüzdan adresi, bir blokzincirde kripto almak için paylaştığınız, açık anahtardan türetilen harf ve rakamlardan oluşan bir dizidir; banka hesap numarasına benzer ama ağa özgüdür."],["two-factor-authentication","İki faktörlü doğrulama (2FA)","İki faktörlü doğrulama (2FA), hesabınıza girişte veya çekimde şifrenin yanında ikinci bir kanıt, örneğin bir doğrulama uygulamasından gelen 6 haneli kod istenmesini sağlayan güvenlik katmanıdır."],["address-poisoning","Adres zehirleme (address poisoning)","Adres zehirleme, dolandırıcının sizin sık kullandığınız adrese benzeyen bir adresten işlem geçmişinize küçük veya sıfır tutarlı transferler göndererek, bir sonraki transferinizde yanlış adresi kopyalamanızı sağlamaya çalıştığı saldırıdır."],["anti-phishing-code","Oltalama karşıtı kod (anti-phishing code)","Oltalama karşıtı kod, borsa hesabınızda belirlediğiniz ve borsanın size gönderdiği gerçek e-postalarda görünen kişisel bir kelimedir; bu kodu içermeyen e-postaların sahte olma ihtimali yüksektir."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Transferden önce: Bunların hiçbirini tahminle yapma"},"coin":null,"tool":null,"cta":false},"crypto-backed-stablecoin":{"slug":"crypto-backed-stablecoin","cat":"stablecoins","en":"Crypto-backed stablecoin","contentLocale":"tr","term":"Kripto teminatlı stablecoin","aka":["kripto destekli stablecoin","crypto-backed stablecoin","aşırı teminatlı stablecoin"],"short":"Kripto teminatlı stablecoin, dolar rezervi yerine akıllı sözleşmede kilitlenen ETH gibi kripto varlıklarla, genellikle değerinden fazla teminatla desteklenen stablecoin'dir.","body":[[["USDT","usdt"]," ve ",["USDC","usdc"]," gibi ",["stablecoin","stablecoin"],"'ler bankada ve hazine bonolarında tutulan rezervlere dayanır. Kripto teminatlı modelde ise teminat zincir üstündedir. Kullanıcı ",["ETH","ethereum"]," gibi bir varlığı bir protokole kilitler ve karşılığında stablecoin basar. Bilinen örnek, MakerDAO'nun çıkardığı DAI'dir (bugün Sky ekosistemi altında da anılır)."],"Kripto fiyatları çok oynak olduğu için bu sistemler aşırı teminat ister. Örneğin 100 dolarlık stablecoin basmak için 150 dolar veya daha fazla teminat yatırmanız gerekebilir. Teminat değeri belirli bir oranın altına düşerse protokol pozisyonu likidasyona (tasfiyeye) gönderir ve teminatı satarak borcu kapatır.",["Avantajı şeffaflıktır: teminatı herkes zincir üstünde görebilir. Dezavantajı ise ",["akıllı sözleşme","smart-contract"]," riski, oracle (fiyat besleme) hataları ve sert düşüşlerde toplu likidasyonlardır."]],"example":["ETH'nin 3.000 dolar olduğunu ve protokolün en az yüzde 150 teminat oranı istediğini varsayalım. 2 ETH, yani 6.000 dolar yatırırsınız. Bu teminatla en fazla 4.000 stablecoin basabilirsiniz, çünkü 6.000 / 4.000 = yüzde 150. Güvenli kalmak için yalnızca 3.000 basarsınız; oranınız yüzde 200 olur. ETH 2.250 dolara düşerse teminatınız 4.500 dolar eder ve oranınız yüzde 150'ye iner. Bu noktada ",["likidasyon","liquidation"]," başlar, teminatınızın bir kısmı ceza ile birlikte satılır."],"mistakes":["Teminat oranını sınırın hemen üstünde tutup küçük bir düşüşte likide olmak.","Basılan stablecoin'i borç değil gelir gibi görüp geri ödeme planı yapmamak.","Likidasyon cezasını ve protokol ücretlerini hesaba katmamak."],"faq":[{"q":"DAI kripto teminatlı bir stablecoin mi?","a":"DAI, kripto teminatlı modelin en bilinen örneğidir. Zamanla teminat sepetine USDC gibi başka stablecoin'ler ve gerçek dünya varlıkları da eklenmiştir."},{"q":"Neden aşırı teminat gerekiyor?","a":"Kripto teminatın değeri hızlı düşebilir. Aradaki fazla teminat, fiyat düşse bile basılan stablecoin'in arkasında yeterli değer kalmasını sağlar."}],"title":"Kripto teminatlı stablecoin nedir? DAI örneğiyle","description":"Kripto teminatlı stablecoin nasıl çalışır, neden aşırı teminat ister ve likidasyon hangi oranda başlar; sayısal örnekle anlatıyoruz.","related":[["stablecoin","Stablecoin (sabit coin)","Stablecoin, değerini genellikle ABD doları gibi bir referans varlığa sabitlemeyi amaçlayan ve kripto piyasasında nakit gibi kullanılan bir kripto paradır."],["defi-lending","DeFi borç verme (DeFi lending)","DeFi borç verme, kullanıcıların kripto varlıklarını akıllı sözleşme havuzlarına yatırarak faiz kazandığı, başkalarının da bu havuzlardan teminat göstererek borç aldığı merkeziyetsiz kredi sistemidir."],["liquidation","Likidasyon (Tasfiye)","Likidasyon (tasfiye), kaldıraçlı bir pozisyonun teminatı bakım seviyesinin altına düştüğünde borsanın pozisyonu zorla kapatmasıdır."],["algorithmic-stablecoin","Algoritmik stablecoin","Algoritmik stablecoin, fiyatını tam rezerv yerine arz-talebi otomatik ayarlayan kurallar ve çoğu zaman ikinci bir token ile 1 dolarda tutmaya çalışan stablecoin türüdür."]],"lesson":null,"coin":{"slug":"dai","name":"Dai","symbol":"DAI"},"tool":null,"cta":false},"block-explorer":{"slug":"block-explorer","cat":"onchain","en":"Block explorer","contentLocale":"tr","term":"Blok gezgini (block explorer)","aka":["block explorer","blockchain gezgini","explorer"],"short":"Blok gezgini, bir blockchain'deki işlemleri, adresleri ve blokları herkesin arama yapıp görebileceği şekilde listeleyen web tabanlı bir araçtır.","body":[["Her ",["blockchain","blockchain"],"'in kendi gezgini vardır. ",["Ethereum","ethereum"]," için Etherscan, BNB Chain için BscScan, Tron için Tronscan, ",["Bitcoin","bitcoin"]," için ",["mempool","mempool"],".space veya Blockchain.com gibi siteler kullanılır. İşlem kimliğini (",["TxID","transaction-hash"]," veya transaction hash), cüzdan adresini ya da blok numarasını arama kutusuna yazarsınız."],"Borsadan çekim yaptığınızda para gelmediyse ilk bakacağınız yer burasıdır. Gezgin size işlemin durumunu (beklemede, onaylandı, başarısız), kaç onay aldığını, ödenen gas ücretini, gönderen ve alan adresi gösterir.",["Önemli bir nokta: doğru ağın gezginini kullanmalısınız. ",["USDT","usdt"]," birçok ağda var; TRC20 ile gönderilen bir işlemi Etherscan'de ararsanız bulamazsınız. Ayrıca gezgin yalnızca okunur bir araçtır; cüzdan bağlamanızı veya kurtarma ifadesi girmenizi asla istemez."]],"example":"Bir borsadan 500 USDT'yi TRC20 ağıyla çektiğinizi ve 20 dakika geçtiği hâlde paranın gelmediğini düşünün. Borsanın çekim geçmişinden TxID'yi kopyalayıp Tronscan'de aratırsınız. Durum 'onaylandı', alıcı adres sizinki ve tutar 499 USDT görünüyor; 1 USDT çekim ücreti kesilmiş. Demek ki sorun zincirde değil, karşı platformun yatırmayı hesaba işlemesinde. Bu ekran görüntüsüyle destek ekibine başvurmak süreci hızlandırır.","mistakes":["İşlemi yanlış ağın gezgininde arayıp 'kayboldu' sanmak.","Gezgin gibi görünen sahte bir sitede cüzdan bağlamak veya kurtarma ifadesi girmek.","Borsa içi transferlerin de zincirde görüneceğini beklemek; çoğu dahili transfer zincire yazılmaz."],"faq":[{"q":"TxID nerede bulunur?","a":"Borsada çekim geçmişinde, cüzdanda ise işlem detaylarında yer alır. Bu kodu ilgili ağın blok gezginine yapıştırarak işlemi takip edebilirsiniz."},{"q":"Blok gezgini güvenli mi?","a":"Gezgin sadece herkese açık veriyi gösterdiği için aramak güvenlidir. Ancak adresi doğru yazdığınızdan emin olun ve gezgin üzerinden cüzdan bağlama isteklerine dikkat edin."}],"title":"Blok gezgini nedir? İşlem nasıl takip edilir","description":"Blok gezgini nedir, TxID ile transferinizi nasıl takip edersiniz ve doğru ağın gezginini seçmek neden önemlidir, öğrenin.","related":[["transaction-hash","İşlem hash'i (TxID)","İşlem hash'i (TxID), blokzincire gönderilen her işleme verilen benzersiz kimlik kodudur ve işlemin durumunu bir blok gezgininde takip etmenizi sağlar."],["block-confirmations","Blok onayı (confirmation)","Blok onayı, bir işlemin bir bloğa eklenmesinden sonra üzerine eklenen her yeni bloğu ifade eder; onay sayısı arttıkça işlemin geri alınması pratikte imkânsız hâle gelir."],["wallet-address","Cüzdan adresi (wallet address)","Cüzdan adresi, bir blokzincirde kripto almak için paylaştığınız, açık anahtardan türetilen harf ve rakamlardan oluşan bir dizidir; banka hesap numarasına benzer ama ağa özgüdür."],["on-chain-analysis","Zincir üstü analiz (on-chain analiz)","Zincir üstü analiz, blockchain'de herkese açık kayıtlı işlemleri, adres hareketlerini ve borsa akışlarını inceleyerek piyasa davranışını anlamaya çalışan analiz yöntemidir."]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"Gönderildi yazıyor ama ulaşmadı. Nereye bakmalısın?"},"coin":null,"tool":null,"cta":false},"travel-rule":{"slug":"travel-rule","cat":"regulation","en":"Travel rule","contentLocale":"tr","term":"Seyahat kuralı (travel rule)","aka":["travel rule","seyahat kuralı","FATF Tavsiye 16"],"short":"Seyahat kuralı (travel rule), kripto hizmet sağlayıcılarının belirli transferlerde gönderen ve alıcı bilgilerini birbirine iletmesini zorunlu kılan, FATF'ın 16 numaralı tavsiyesine dayanan kuraldır.","body":[["Bankalar havale yaparken gönderen ve alıcı bilgilerini birlikte iletir. FATF bu mantığı kripto hizmet sağlayıcılarına (",["VASP","vasp"],") da uyguladı. FATF rehberinde eşik genellikle 1.000 dolar veya euro olarak geçer. AB ise 30 Aralık 2024'ten itibaren ilk eurodan başlayarak uyguluyor. Ülkeler eşiği ve ayrıntıları farklı belirleyebilir."],"Kullanıcı olarak bunu çekim ekranında görürsünüz. Borsa, alıcının adını, alıcı adresin bir borsaya mı yoksa kendi cüzdanınıza mı ait olduğunu ve hangi platform olduğunu sorabilir. Kendi cüzdanınıza çekimlerde cüzdan sahipliğini kanıtlamanız istenebilir.","Bilgiler eksik veya uyumsuzsa transfer bekletilebilir veya iade edilebilir. Bu yüzden ilk kez yeni bir adrese büyük tutar göndermeden önce küçük bir deneme transferi yapmak ve istenen bilgileri doğru doldurmak işinizi kolaylaştırır."],"example":["AB'de lisanslı bir borsadan başka bir borsadaki hesabınıza 1.500 ",["USDC","usdc"]," göndermek istediğinizi varsayalım. Çekim ekranı alıcı platformun adını ve hesabın size ait olup olmadığını sorar. 'Kendi hesabım' seçip adınızı doğru girersiniz. Karşı borsa da bu bilgiyi kendi kayıtlarıyla eşleştirir ve yatırma 1.499 USDC olarak, 1 USDC ",["ağ ücreti","gas-fee"]," düşülerek hesabınıza geçer. Adınızı farklı yazsaydınız transfer manuel incelemeye düşebilir ve günlerce bekleyebilirdi."],"mistakes":["Çekim ekranındaki alıcı bilgilerini rastgele veya eksik doldurmak.","Alıcı platformu yanlış seçip transferin iade edilmesine neden olmak.","Kendi cüzdanına çekimde sahiplik doğrulamasını atlamaya çalışmak."],"faq":[{"q":"Travel rule neden alıcının adını soruyor?","a":"Kural, hizmet sağlayıcıların gönderen ve alıcı bilgisini transferle birlikte iletmesini gerektirir. Bu bilgi kara para aklama ve yaptırım kontrolleri için kullanılır."},{"q":"Kendi cüzdanıma çekim yaparken de geçerli mi?","a":"Birçok ülkede evet; borsa bu durumda adresin size ait olduğunu beyan etmenizi veya imza ile kanıtlamanızı isteyebilir. Uygulama ülkeye ve borsaya göre değişir."}],"title":"Travel rule nedir? Kripto transferinde seyahat kuralı","description":"Seyahat kuralı (travel rule) nedir, çekimde neden alıcı bilgisi istenir ve transferin takılmaması için nelere dikkat etmelisiniz.","related":[["kyc","KYC (müşterini tanı)","KYC (Know Your Customer, müşterini tanı), kripto borsalarının ve finansal kuruluşların kullanıcının kimliğini, adresini ve bazen gelir kaynağını doğruladığı zorunlu kimlik doğrulama sürecidir."],["aml","AML (kara para aklamayı önleme)","AML (Anti-Money Laundering), suç gelirlerinin finansal sistemde temiz para gibi gösterilmesini önlemeye yönelik yasal kurallar, kontroller ve izleme süreçlerinin bütünüdür."],["vasp","VASP (sanal varlık hizmet sağlayıcısı)","VASP (Virtual Asset Service Provider), başkaları adına kripto varlık alım satımı, takası, transferi veya saklaması yapan ve bu nedenle düzenlemeye tabi olan şirketlerdir."],["withdrawal-whitelist","Çekim beyaz listesi (withdrawal whitelist)","Çekim beyaz listesi, borsa hesabınızdan yalnızca önceden kaydedip onayladığınız adreslere kripto çekilmesine izin veren bir güvenlik ayarıdır."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Transferden önce: Bunların hiçbirini tahminle yapma"},"coin":null,"tool":null,"cta":false},"spot-bitcoin-etf":{"slug":"spot-bitcoin-etf","cat":"regulation","en":"Spot bitcoin ETF","contentLocale":"tr","term":"Spot Bitcoin ETF","aka":["Bitcoin ETF","spot BTC ETF","spot bitcoin borsa yatırım fonu"],"short":"Spot Bitcoin ETF, gerçek bitcoin satın alıp saklayan ve borsada hisse senedi gibi işlem gören, fiyatı bitcoin'in piyasa fiyatını takip eden bir borsa yatırım fonudur.","body":[["ABD'de spot Bitcoin ETF'leri Ocak 2024'te işlem görmeye başladı. BlackRock'un IBIT'i ve Fidelity'nin FBTC'si bilinen örneklerdir. Yatırımcı bir aracı kurum hesabından ETF payı alır; fon ise karşılığında ",["bitcoin","bitcoin"],"'i bir saklayıcıda tutar."],"Önceki vadeli işlem tabanlı ETF'ler bitcoin'in kendisini değil vadeli kontratları tutuyordu. Spot ETF'ler doğrudan bitcoin tuttuğu için fiyat takibi genelde daha yakındır.",["Avantajları: cüzdan, ",["özel anahtar","private-key"]," veya borsa hesabıyla uğraşmazsınız. Dezavantajları: yıllık yönetim ücreti ödersiniz, payları yalnızca piyasa saatlerinde alıp satarsınız ve bitcoin'i zincir üstünde kendinize çekemezsiniz. Türkiye'den bu fonlara erişim, aracı kurumunuzun yurt dışı piyasa hizmetine bağlıdır."]],"example":"Bir spot Bitcoin ETF'sinin yıllık yüzde 0,25 yönetim ücreti aldığını varsayalım. 10.000 dolar yatırırsınız. Bitcoin bir yılda yüzde 20 yükselirse fonunuz ücretten önce 12.000 dolara çıkar. Ücret yaklaşık olarak ortalama varlık üzerinden kesildiği için yıl boyunca 25 ile 30 dolar arası öder, yaklaşık 11.972 dolarla yılı kapatırsınız. Aynı tutarı doğrudan BTC alıp kendi cüzdanınızda tutsaydınız yönetim ücreti olmazdı ama alım-çekim ücretlerini ve saklama sorumluluğunu siz üstlenirdiniz.","mistakes":["ETF payının size zincir üstünde bitcoin verdiğini düşünmek.","Yönetim ücretini ve aracı kurum komisyonlarını hesaba katmamak.","ETF'nin hafta sonu ve gece de işlem gördüğünü sanmak."],"faq":[{"q":"Spot Bitcoin ETF ile bitcoin almak arasındaki fark nedir?","a":"ETF'de bitcoin'e fiyat üzerinden maruz kalırsınız ama coin'in kendisi fonun saklayıcısındadır. Doğrudan alımda ise coin sizindir ve isterseniz kendi cüzdanınıza çekebilirsiniz."},{"q":"Türkiye'den spot Bitcoin ETF alınabilir mi?","a":"Bu, yurt dışı piyasalara erişim sunan bir aracı kurum hesabınız olup olmadığına ve kurumun ilgili ürünü sunmasına bağlıdır. Vergi uygulamasını da ayrıca kontrol etmeniz gerekir."}],"title":"Spot Bitcoin ETF nedir? Nasıl çalışır","description":"Spot Bitcoin ETF nedir, doğrudan bitcoin almaktan farkı nedir ve yönetim ücreti getiriyi nasıl etkiler, örnekle öğrenin.","related":[["bitcoin","Bitcoin (BTC)","Bitcoin (BTC), 2009'da Satoshi Nakamoto takma adıyla başlatılan, iş ispatı ile çalışan ve toplam arzı 21 milyon BTC ile sınırlı olan ilk ve piyasa değeri en büyük kripto paradır."],["tokenized-stocks","Tokenize hisse senetleri","Tokenize hisse senetleri, bir şirketin hisse senedinin fiyatını takip eden ve genellikle bir saklayıcıda tutulan gerçek hisseyle desteklenen, blockchain üzerinde işlem gören token'lardır."],["custodial-wallet","Emanetçi cüzdan (Custodial wallet)","Emanetçi cüzdan (custodial wallet), kripto varlıklarınızın özel anahtarlarını sizin yerinize bir borsanın veya saklama kuruluşunun tuttuğu cüzdan türüdür."],["market-capitalization","Piyasa değeri (market cap)","Piyasa değeri (market cap), bir kripto paranın güncel fiyatının dolaşımdaki arzla çarpılmasıyla bulunan toplam değerdir ve coinlerin büyüklüğünü karşılaştırmak için kullanılır."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"geo-restrictions":{"slug":"geo-restrictions","cat":"regulation","en":"Geo-restrictions (restricted regions)","contentLocale":"tr","term":"Bölge kısıtlamaları (geo-restrictions)","aka":["geo-restriction","coğrafi kısıtlama","kısıtlı ülkeler","yasaklı bölgeler"],"short":"Bölge kısıtlamaları, bir kripto borsasının veya ürünün yasal ve düzenleyici nedenlerle belirli ülkelerde yaşayan kullanıcılara hizmet vermemesi ya da bazı özellikleri kapatmasıdır.","body":[["Borsalar her ülkenin kurallarına uymak zorundadır. Bu yüzden kullanım koşullarında 'kısıtlı ülkeler' listesi bulunur. Örneğin bazı uluslararası borsalar ABD'de yaşayanlara hizmet vermez; AB'de ",["MiCA","mica"]," kurallarına göre belirli ",["stablecoin","stablecoin"],"'ler kısıtlanmıştır; bazı ülkelerde kaldıraçlı ",["vadeli işlemler","futures-contract"]," bireysel kullanıcılara kapalıdır."],["Kısıtlama tüm platformu veya sadece belirli ürünleri kapsayabilir: vadeli işlemler, ",["kopya işlem","copy-trading"],", earn ürünleri ya da belirli token'lar. Borsa bunu ",["KYC","kyc"],"'deki ülke bilginize ve IP adresinize göre belirler."],"VPN ile kısıtlamayı aşmaya çalışmak riskli bir yoldur. Borsalar bunu kullanım koşullarının ihlali sayar; hesap kapatılabilir ve fonların iadesi uzun sürebilir. Doğru yaklaşım, yaşadığınız ülkede hizmet vermeye yetkili bir platform seçmektir."],"example":["Bir borsada 2.000 ",["USDT","usdt"]," ile vadeli işlem yaptığınızı ve başka bir ülkeye taşındığınızı düşünün. Yeni ülkenizde bu borsanın vadeli ürünleri kısıtlı. Adres değişikliğini bildirdiğinizde borsa size açık pozisyonları 30 gün içinde kapatmanızı söyler; sonrasında yalnızca spot işlem ve çekim yapabilirsiniz. Açık pozisyonu süre içinde kapatmazsanız borsa piyasa fiyatından kendisi kapatabilir. Bu yüzden ülke değiştirmeden önce kullandığınız ürünlerin yeni ülkede açık olup olmadığını kontrol etmek gerekir."],"mistakes":["Kısıtlı bir ülkeden VPN ile hesap açıp hesabın sonsuza kadar çalışacağını sanmak.","KYC'de gerçek ikamet ülkesi yerine farklı bir ülke beyan etmek.","Kullanım koşullarındaki kısıtlı ürünler listesini hiç okumamak."],"faq":[{"q":"Borsa neden ülkemde hizmet vermiyor?","a":"Çoğu zaman o ülkede gerekli lisansa sahip olmadığı veya yerel kurallar belirli ürünleri yasakladığı içindir. Bazen borsa ticari nedenlerle de bir pazardan çekilebilir."},{"q":"VPN kullanırsam ne olur?","a":"Borsa bunu tespit ederse hesabı kısıtlayabilir veya kapatabilir ve fonların iadesi için ek doğrulama isteyebilir. Kullanım koşullarının ihlali sayıldığı için korunma hakkınız zayıflar."}],"title":"Bölge kısıtlaması nedir? Kripto borsalarında kısıtlı ülkeler","description":"Kripto borsalarında bölge kısıtlaması nedir, hangi ürünler kapatılabilir ve VPN kullanmak neden hesabınızı riske atar, öğrenin.","related":[["kyc","KYC (müşterini tanı)","KYC (Know Your Customer, müşterini tanı), kripto borsalarının ve finansal kuruluşların kullanıcının kimliğini, adresini ve bazen gelir kaynağını doğruladığı zorunlu kimlik doğrulama sürecidir."],["vasp","VASP (sanal varlık hizmet sağlayıcısı)","VASP (Virtual Asset Service Provider), başkaları adına kripto varlık alım satımı, takası, transferi veya saklaması yapan ve bu nedenle düzenlemeye tabi olan şirketlerdir."],["no-kyc-exchange","KYC'siz borsa (no-KYC exchange)","KYC'siz borsa, hesap açmak ve belirli limitlere kadar işlem yapmak için kimlik doğrulaması istemeyen merkezi veya merkeziyetsiz kripto alım satım platformudur."],["centralized-exchange","Merkezi borsa (CEX)","Merkezi borsa (CEX), bir şirket tarafından işletilen, kullanıcıların fonlarını saklayan ve alıcılarla satıcıları kendi emir defterinde eşleştiren kripto para alım satım platformudur."]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"KYC nasıl yapılır ve kimlik kime verilmelidir?"},"coin":null,"tool":"/exchanges","cta":false},"delisting":{"slug":"delisting","cat":"exchange-features","en":"Delisting","contentLocale":"tr","term":"Delisting (borsadan çıkarma)","aka":["delist","delisting","borsadan çıkarılma","listeden çıkarma"],"short":"Delisting, bir borsanın bir token'ın veya işlem çiftinin alım satımını durdurup ardından yatırma ve çekim hizmetlerini de kapatarak o varlığı platformdan kaldırmasıdır.","body":[["Borsalar listeledikleri token'ları düzenli olarak gözden geçirir. Düşük işlem hacmi ve ",["likidite","liquidity"],", geliştirmenin durması, güvenlik sorunları, yasal veya düzenleyici gereklilikler ve proje ekibinin taahhütlerini yerine getirmemesi delisting nedenleri arasındadır."],["Süreç genellikle aşamalıdır. Borsa önce bir duyuru yapar ve işlemlerin durdurulacağı tarihi bildirir. İşlem durunca kalan bakiyeyi sadece çekebilirsiniz. Belirli bir süre sonra çekim de kapanır. Bazı borsalar kalan bakiyeleri belli bir süre sonra ",["stablecoin","stablecoin"],"'e çevirebilir, bazıları bunu yapmaz."],"Delisting duyurusu çoğu zaman sert fiyat düşüşü ve likidite kaybı getirir. Böyle bir token'ı tutuyorsanız duyurudaki tarihleri not etmek ve token'ı destekleyen başka bir platform veya cüzdan bulmak önemlidir."],"example":["Elinizde 50.000 adet ABC token'ı olduğunu ve fiyatın 0,04 ",["USDT","usdt"],", yani toplam 2.000 USDT olduğunu varsayalım. Borsa, işlemin 10 gün sonra duracağını ve çekimlerin 3 ay daha açık kalacağını duyurur. Duyuru sonrası fiyat yüzde 40 düşerek 0,024 USDT'ye iner; bakiyeniz 1.200 USDT eder. Satmak istemezseniz token'ı destekleyen bir cüzdana çekmeniz gerekir. ",["Çekim ücreti","withdrawal-fee"]," 500 ABC ise cüzdanınıza 49.500 ABC ulaşır. Çekim süresini kaçırırsanız token'lara erişiminiz zorlaşabilir."],"mistakes":["Borsanın delisting duyurularını takip etmeyip çekim süresini kaçırmak.","Duyurudan sonra fiyatın mutlaka toparlanacağını varsaymak.","Token'ı, o ağı ve token'ı desteklemeyen bir cüzdana çekmek."],"faq":[{"q":"Delist edilen coin'lerime ne olur?","a":"İşlemler durduktan sonra belirli bir süre çekim yapabilirsiniz. Süre sona erdikten sonra ne olacağı borsanın politikasına bağlıdır; duyuruyu dikkatle okumak gerekir."},{"q":"Delisting coin'in değersiz olduğu anlamına mı gelir?","a":"Her zaman değil. Bir borsa düzenleyici veya ticari nedenlerle de çıkarabilir ve token başka platformlarda işlem görmeye devam edebilir. Ancak likidite genellikle azalır."}],"title":"Delisting nedir? Coin borsadan çıkarılınca ne olur","description":"Delisting nedir, borsalar coin'leri neden listeden çıkarır, işlem ve çekim süreleri nasıl işler ve bakiyenizi nasıl korursunuz.","related":[["token-listing","Token listelemesi","Token listelemesi, bir kripto varlığın bir borsada işlem çiftleriyle alınıp satılabilir hâle getirilmesi, yani borsanın o token için yatırma, çekim ve işlem hizmeti açmasıdır."],["liquidity","Likidite (Liquidity)","Likidite, bir varlığın fiyatı fazla etkilenmeden ne kadar hızlı ve kolay alınıp satılabildiğini gösteren ölçüdür."],["withdrawal-fee","Çekim ücreti","Çekim ücreti, bir kripto varlığı borsadan harici bir cüzdana veya başka bir platforma gönderirken borsanın kestiği, genellikle seçilen ağa göre sabit miktarda alınan ücrettir."],["rug-pull","Rug pull (halı çekme)","Rug pull, bir kripto projesinin geliştiricilerinin yatırımcı parasını toplayıp likiditeyi çekerek, token'ları satarak veya akıllı sözleşmedeki gizli yetkileri kullanarak projeyi aniden terk ettiği dolandırıcılıktır."]],"lesson":null,"coin":null,"tool":"/activities","cta":false}});
